import React, { useEffect } from "react";

import { useLocation, useParams } from "react-router-dom";
import useApi from "../../../hooks/useApi";

import { useState } from "react";
import RetailerOrderInvoice from "../../../components/invoice/RetailerOrderInvoice";
import customerOrdersApi from "../../../api/retailers/customerOrdersApi";

function RetailerOrderInvoiceForRetailer(props) {
  const { customer_order_id } = useParams();
  const { state } = useLocation();
  console.log("stt", state);

  //Retrieve order details
  const [selectedOrder, setselectedOrder] = useState(state);

  const [customerOrderId, setcustomerOrderId] = useState(customer_order_id);

  const retrieveOrderDetailsApi = useApi(
    customerOrdersApi.customerOrdersStaffAction
  );

  const retrieveOrderDetails = async () => {
    await retrieveOrderDetailsApi.request({
      action: "CustomerOrderDetails",
      customer_order: customerOrderId,
    });
  };

  useEffect(() => {
    if (customerOrderId) {
      retrieveOrderDetails();
    }

    console.log("customerOrderId", customerOrderId);
  }, [customerOrderId]);

  useEffect(() => {
    if (retrieveOrderDetailsApi.data) {
      if (retrieveOrderDetailsApi.data.customer_order) {
        setselectedOrder(retrieveOrderDetailsApi.data.customer_order);
      }
    }

    console.log("retrieveOrderDetailsApi.data", retrieveOrderDetailsApi.data);
  }, [retrieveOrderDetailsApi.data]);
  return (
    <div>
      {selectedOrder ? (
        <RetailerOrderInvoice order={selectedOrder} />
      ) : (
        <div className="cursor-none">No order selected</div>
      )}
    </div>
  );
}

export default RetailerOrderInvoiceForRetailer;
